import { describe, expect, test } from "bun:test";
import { DAILY_BUMP_LIMIT, MAX_BUMPS } from "./cooldown";
import {
	DEFAULT_RULES,
	MIN_BUMP_AGE_DAYS,
	STALE_EXPOSURE_DAYS,
	atMaxBumps,
	bumpEligible,
	compareBumpOrder,
	exposureAgeDays,
	flowFromNow,
	alreadyAppliedToday,
	guardSnapshot,
	inCooldown,
	linePrice,
	pricePath,
	priceUnit,
	proposeBatch,
	recentlyExposed,
	remainingDays,
	bumpedToday,
	scheduleFor,
	summarize,
	type Listing,
} from "./rules";

const TODAY = "2026-10-26";
const NOW = Date.parse("2026-10-26T10:00:00+09:00");

function listing(overrides: Partial<Listing> & Pick<Listing, "id" | "title" | "price" | "hearts">): Listing {
	return {
		views: 0,
		chats: 0,
		bumpAgoDays: null,
		postedAgoDays: null,
		bumpCount: null,
		bumpedAt: null,
		nextBumpAt: null,
		target: null,
		until: null,
		included: true,
		...overrides,
	};
}

/** 마감이 오늘이면 한 번에 타겟으로 맞춘다. */
function aimed(overrides: Partial<Listing> & Pick<Listing, "id" | "title" | "price" | "hearts" | "target">): Listing {
	return listing({ until: TODAY, ...overrides });
}

function planOf(listings: Listing[], today = TODAY, now = NOW) {
	return proposeBatch(listings, { ...DEFAULT_RULES }, today, now);
}

describe("구간 내림", () => {
	test("단위는 인하 계산값 기준 500 / 1,000 / 5,000", () => {
		expect(priceUnit(9_999.9)).toBe(500);
		expect(priceUnit(10_000)).toBe(1_000);
		expect(priceUnit(99_999)).toBe(1_000);
		expect(priceUnit(100_000)).toBe(5_000);
	});

	test("마지막 날은 타겟을 다시 내림하지 않는다", () => {
		expect(linePrice(300_000, 280_000, 0, 1)).toBe(280_000);
		expect(linePrice(20_000, 17_555, 0, 1)).toBe(17_555);
		expect(linePrice(300_000, 240_000, 3, 4)).toBe(240_000);
		expect(linePrice(10_000, 10_000, 0, 1)).toBe(10_000);
	});

	test("시작가에서 타겟까지 균등하게 나누고 구간으로 내린다", () => {
		expect(linePrice(300_000, 240_000, 0, 4)).toBe(285_000);
		expect(linePrice(50_000, 40_000, 0, 4)).toBe(47_000);
		expect(linePrice(17_550, 15_000, 0, 2)).toBe(16_000);
	});

	test("타겟이 시작가 이상이거나 0 이하면 바꾸지 않는다", () => {
		expect(linePrice(10_000, 12_000, 0, 3)).toBe(10_000);
		expect(linePrice(10_000, 0, 0, 3)).toBe(10_000);
	});

	test("타겟에는 마지막 날에만 닿는다", () => {
		const days = 20;
		const prices = Array.from({ length: days }, (_, index) => linePrice(130_000, 100_000, index, days));
		expect(prices.at(-1)).toBe(100_000);
		expect(prices.slice(0, -1).every((price) => price > 100_000)).toBe(true);
		for (let index = 1; index < days; index += 1) expect(prices[index]).toBeLessThanOrEqual(prices[index - 1]);
	});
});

describe("쭉 내려가는 흐름", () => {
	test("하루 인하폭이 내림 단위보다 작아도 날마다 내려간다", () => {
		const days = 14;
		const prices = Array.from({ length: days }, (_, index) => linePrice(11_000, 8_000, index, days));
		expect(prices.at(-1)).toBe(8_000);
		for (let index = 1; index < days; index += 1) expect(prices[index]).toBeLessThan(prices[index - 1]);
		expect(prices[0]).toBeLessThan(11_000);
	});

	test("인하폭이 100원보다 작으면 100원 단위로 내린다", () => {
		expect(linePrice(20_000, 19_000, 0, 20) % 100).toBe(0);
	});
});

describe("기간", () => {
	test("오늘을 포함한 날 수", () => {
		expect(remainingDays("2026-10-26", "2026-10-26")).toBe(1);
		expect(remainingDays("2026-10-26", "2026-10-29")).toBe(4);
		expect(remainingDays("2026-10-26", "2026-10-25")).toBe(0);
		expect(remainingDays("2026-10-26", "nope")).toBeNull();
	});

	test("마감이 지났으면 오늘 타겟으로 맞춘다", () => {
		const row = listing({
			id: "a",
			title: "가",
			price: 50_000,
			hearts: 0,
			target: 40_000,
			until: "2026-10-20",
		});
		expect(scheduleFor(row, TODAY)).toMatchObject({ price: 40_000, changed: true, remainingDays: 1 });
	});

	test("타겟이나 날짜가 없으면 가격을 내리지 않는다", () => {
		const bare = listing({ id: "a", title: "가", price: 50_000, hearts: 0 });
		expect(scheduleFor(bare, TODAY)).toEqual({ price: 50_000, changed: false, ratio: 0, remainingDays: 0 });
		expect(scheduleFor({ ...bare, target: 40_000 }, TODAY).changed).toBe(false);
		expect(scheduleFor({ ...bare, until: TODAY }, TODAY).changed).toBe(false);
	});

	test("날짜별 가격은 시작가의 직선에서 읽는다", () => {
		expect(pricePath({ price: 300_000, date: TODAY }, 240_000, "2026-10-29", TODAY)).toEqual([
			{ date: "2026-10-26", price: 285_000 },
			{ date: "2026-10-27", price: 270_000 },
			{ date: "2026-10-28", price: 255_000 },
			{ date: "2026-10-29", price: 240_000 },
		]);
	});

	test("일정을 정한 지 하루 지났으면 직선의 둘째 날부터 보여 준다", () => {
		expect(pricePath({ price: 300_000, date: "2026-10-25" }, 240_000, "2026-10-29", TODAY)).toEqual([
			{ date: "2026-10-26", price: 275_000 },
			{ date: "2026-10-27", price: 260_000 },
			{ date: "2026-10-28", price: 250_000 },
			{ date: "2026-10-29", price: 240_000 },
		]);
	});

	test("시작일이 내일이면 오늘은 가격을 내리지 않고 내일부터 직선을 탄다", () => {
		const row = listing({
			id: "a",
			title: "가",
			price: 400_000,
			hearts: 0,
			target: 300_000,
			until: "2026-10-30",
			startPrice: 400_000,
			startDate: "2026-10-27",
		});
		expect(scheduleFor(row, TODAY)).toMatchObject({ price: 400_000, changed: false });
		expect(scheduleFor(row, "2026-10-27").changed).toBe(true);
		const path = pricePath({ price: 400_000, date: "2026-10-27" }, 300_000, "2026-10-30", TODAY);
		expect(path[0]).toEqual({ date: TODAY, price: 400_000 });
		expect(path[1].price).toBe(linePrice(400_000, 300_000, 0, 4));
		expect(path.at(-1)).toEqual({ date: "2026-10-30", price: 300_000 });
	});

	test("시작가·시작일이 있으면 오늘 몫은 그 직선의 오늘 값이다", () => {
		const row = listing({
			id: "a",
			title: "가",
			price: 285_000,
			hearts: 0,
			target: 240_000,
			until: "2026-10-29",
			startPrice: 300_000,
			startDate: "2026-10-25",
		});
		expect(scheduleFor(row, TODAY)).toMatchObject({ price: 275_000, changed: true, remainingDays: 4 });
	});

	test("이미 직선보다 낮으면 올리지 않는다", () => {
		const row = listing({
			id: "a",
			title: "가",
			price: 250_000,
			hearts: 0,
			target: 240_000,
			until: "2026-10-29",
			startPrice: 300_000,
			startDate: TODAY,
		});
		expect(scheduleFor(row, TODAY)).toMatchObject({ price: 250_000, changed: false });
	});
});

describe("노출 나이", () => {
	test("끌올 문구가 있으면 그것, 없으면 게시 시점이 노출 나이다", () => {
		expect(exposureAgeDays({ bumpAgoDays: 4, postedAgoDays: 21 })).toBe(4);
		expect(exposureAgeDays({ bumpAgoDays: null, postedAgoDays: 21 })).toBe(21);
		expect(exposureAgeDays({ bumpAgoDays: null, postedAgoDays: null })).toBeNull();
		expect(exposureAgeDays({ bumpAgoDays: null })).toBeNull();
	});

	test("노출이 2일 미만인 글만 최근 노출이다", () => {
		expect(MIN_BUMP_AGE_DAYS).toBe(2);
		expect(recentlyExposed({ bumpAgoDays: 1 })).toBe(true);
		expect(recentlyExposed({ bumpAgoDays: null, postedAgoDays: 1 })).toBe(true);
		expect(recentlyExposed({ bumpAgoDays: 2 })).toBe(false);
		expect(recentlyExposed({ bumpAgoDays: null, postedAgoDays: null })).toBe(false);
	});

	test("노출이 오래된 글은 하트가 적은 글보다 먼저다", () => {
		const quiet = listing({ id: "quiet", title: "가", price: 10_000, hearts: 1, bumpAgoDays: 4 });
		const stale = listing({
			id: "stale",
			title: "나",
			price: 10_000,
			hearts: 7,
			bumpAgoDays: null,
			postedAgoDays: 21,
		});
		const sorted = [quiet, stale].sort((left, right) => compareBumpOrder(left, right, TODAY));
		expect(sorted.map((item) => item.id)).toEqual(["stale", "quiet"]);
	});

	test("끌올한 적 없이 게시만 한 글도 게시 나이로 끼어든다", () => {
		const bumped = listing({ id: "bumped", title: "가", price: 10_000, hearts: 0, bumpAgoDays: 1 });
		const posted = listing({
			id: "posted",
			title: "나",
			price: 10_000,
			hearts: 9,
			bumpAgoDays: null,
			postedAgoDays: 3,
		});
		const sorted = [bumped, posted].sort((left, right) => compareBumpOrder(left, right, TODAY));
		expect(sorted.map((item) => item.id)).toEqual(["posted", "bumped"]);
	});

	test("노출 나이가 같으면 마감 빠른 순 → 하트 적은 순 → 가격 높은 순", () => {
		const rows = [
			listing({ id: "a", title: "가", price: 100_000, hearts: 2, bumpAgoDays: 5, until: "2026-10-29" }),
			listing({ id: "b", title: "나", price: 100_000, hearts: 0, bumpAgoDays: 5, until: "2026-10-29" }),
			listing({ id: "c", title: "다", price: 100_000, hearts: 2, bumpAgoDays: 5, until: "2026-10-27" }),
			listing({ id: "d", title: "라", price: 200_000, hearts: 2, bumpAgoDays: 5, until: "2026-10-29" }),
		];
		const sorted = rows.sort((left, right) => compareBumpOrder(left, right, TODAY)).map((item) => item.id);
		expect(sorted).toEqual(["c", "b", "d", "a"]);
	});

	test("노출 나이가 같으면 하트가 많아도 마감이 가까운 글이 먼저다(휘센이 하트 때문에 밀린 날)", () => {
		const hwisen = listing({ id: "hwisen", title: "LG 휘센", price: 110_000, hearts: 4, bumpAgoDays: 5, until: "2026-10-28" });
		const ulanzi = listing({ id: "ulanzi", title: "울란지", price: 26_000, hearts: 3, bumpAgoDays: 5, until: "2026-11-20" });
		const sorted = [ulanzi, hwisen].sort((left, right) => compareBumpOrder(left, right, TODAY));
		expect(sorted.map((item) => item.id)).toEqual(["hwisen", "ulanzi"]);
		const fillers = Array.from({ length: 5 }, (_, index) =>
			listing({ id: `f${index}`, title: `f${index}`, price: 10_000, hearts: 0, bumpAgoDays: 5, until: "2026-11-20" }),
		);
		const bumped = planOf([...fillers, ulanzi, hwisen])
			.filter((proposal) => proposal.action === "bump")
			.map((proposal) => proposal.id);
		expect(bumped).toHaveLength(6);
		expect(bumped).toContain("hwisen");
		expect(bumped).not.toContain("ulanzi");
	});

	test("노출이 2일 미만이면 fresh 로 건너뛰고 하루 칸도 쓰지 않는다", () => {
		const recent = listing({ id: "r", title: "r", price: 10_000, hearts: 0, bumpAgoDays: 1 });
		const [proposal] = planOf([recent]);
		expect(proposal).toMatchObject({ action: "skip", skipReason: "fresh", blocked: "fresh" });
		expect(summarize([proposal]).held).toBe(0);
	});

	test("끌올한 적 없는 새 글도 게시 나이로 fresh 다", () => {
		const [proposal] = planOf([
			listing({ id: "p", title: "p", price: 10_000, hearts: 0, bumpAgoDays: null, postedAgoDays: 1 }),
		]);
		expect(proposal).toMatchObject({ action: "skip", skipReason: "fresh" });
	});

	test("fresh 글도 내릴 가격이 있으면 가격만 내린다", () => {
		const [proposal] = planOf([
			aimed({ id: "f", title: "f", price: 50_000, hearts: 0, target: 45_000, bumpAgoDays: 1 }),
		]);
		expect(proposal).toMatchObject({ action: "price-only", skipReason: null, blocked: "fresh", price: 45_000 });
	});

	test("노출 시점을 못 읽은 글은 막지 않고 맨 앞에 둔다", () => {
		const unknown = listing({ id: "u", title: "가", price: 10_000, hearts: 9 });
		const day3 = listing({ id: "d", title: "나", price: 10_000, hearts: 0, bumpAgoDays: 3 });
		expect(planOf([unknown])[0].action).toBe("bump");
		const sorted = [day3, unknown].sort((left, right) => compareBumpOrder(left, right, TODAY));
		expect(sorted.map((item) => item.id)).toEqual(["u", "d"]);
	});
});

describe("승인 화면의 제안", () => {
	const rows: { name: string; input: Listing; action: "bump" | "price-only" | "skip"; price: number; note?: string }[] =
		[
			{
				name: "하트 0 · 오늘 타겟 45,000",
				input: aimed({ id: "a", title: "가", price: 50_000, hearts: 0, target: 45_000 }),
				action: "bump",
				price: 45_000,
			},
			{
				name: "하트 2 · 오늘 타겟 5,000",
				input: aimed({ id: "b", title: "나", price: 6_000, hearts: 2, target: 5_000 }),
				action: "bump",
				price: 5_000,
			},
			{
				name: "하트 1 · 오늘 타겟 15,000",
				input: aimed({ id: "c", title: "다", price: 17_550, hearts: 1, target: 15_000 }),
				action: "bump",
				price: 15_000,
			},
			{
				name: "하트 0 · 오늘 타겟 225,000",
				input: aimed({ id: "d", title: "라", price: 255_300, hearts: 0, target: 225_000 }),
				action: "bump",
				price: 225_000,
			},
			{
				name: "하트 3 · 오늘 타겟 49,000",
				input: aimed({ id: "e", title: "마", price: 50_000, hearts: 3, target: 49_000 }),
				action: "bump",
				price: 49_000,
			},
			{
				name: "하트 8 · 오늘 타겟 295,000",
				input: aimed({ id: "f", title: "바", price: 300_000, hearts: 8, target: 295_000 }),
				action: "bump",
				price: 295_000,
			},
			{
				name: "하트 1 · 타겟=현재가 → 가격 유지, 끌올만",
				input: aimed({ id: "g", title: "사", price: 10_000, hearts: 1, target: 10_000 }),
				action: "bump",
				price: 10_000,
				note: "floor-reached",
			},
			{
				name: "하트 5 · 타겟=현재가 → 가격 유지, 끌올만",
				input: aimed({ id: "h", title: "아", price: 10_000, hearts: 5, target: 10_000 }),
				action: "bump",
				price: 10_000,
				note: "floor-reached",
			},
			{
				name: "하트 2 · 오늘 타겟 280,000",
				input: aimed({ id: "i", title: "자", price: 300_000, hearts: 2, target: 280_000 }),
				action: "bump",
				price: 280_000,
			},
			{
				name: "하트 0 · 타겟·날짜 없음 → 끌올만, 가격 유지",
				input: listing({ id: "j", title: "차", price: 50_000, hearts: 0 }),
				action: "bump",
				price: 50_000,
			},
			{
				name: "하트 5 · 타겟·날짜 없음 → 끌올만, 가격 유지",
				input: listing({ id: "k", title: "카", price: 50_000, hearts: 5 }),
				action: "bump",
				price: 50_000,
			},
		];

	for (const row of rows) {
		test(row.name, () => {
			const [proposal] = planOf([row.input]);
			expect(proposal.action).toBe(row.action);
			expect(proposal.price).toBe(row.price);
			expect(proposal.note).toBe("note" in row ? "floor-reached" : null);
		});
	}

	test("타겟 도달한 끌어올리기는 가격을 바꾸지 않은 것으로 표시한다", () => {
		const [proposal] = planOf([aimed({ id: "g", title: "사", price: 10_000, hearts: 1, target: 10_000 })]);
		expect(proposal.priceChanged).toBe(false);
	});

	test("하루 칸이 다 차면 내릴 가격도 없는 글은 daily-limit 으로 건너뛴다", () => {
		const already = Array.from({ length: 6 }, (_, index) =>
			listing({ id: `p${index}`, title: `p${index}`, price: 10_000, hearts: 0, until: TODAY }),
		);
		const stuck = aimed({ id: "h", title: "아", price: 10_000, hearts: 5, target: 10_000 });
		const proposal = planOf([...already, stuck]).find((item) => item.id === "h");
		expect(proposal).toMatchObject({ action: "skip", skipReason: "daily-limit", blocked: "daily-limit" });
	});

	test("오늘 인하분을 %로 남긴다", () => {
		const [proposal] = planOf([aimed({ id: "a", title: "가", price: 50_000, hearts: 0, target: 45_000 })]);
		expect(proposal.ratio).toBe(10);
	});
});

describe("하루 한도와 순서", () => {
	test("끌어올리기 대상 8개 중 6개만, 나머지는 daily-limit", () => {
		const eight = Array.from({ length: 8 }, (_, index) =>
			listing({ id: `p${index}`, title: String.fromCharCode(65 + index), price: 10_000, hearts: 0 }),
		);
		const summary = summarize(planOf(eight));
		expect(summary.bump).toBe(6);
		expect(summary.held).toBe(2);
		expect(
			planOf(eight)
				.filter((proposal) => proposal.action === "skip")
				.map((proposal) => proposal.id),
		).toEqual(["p6", "p7"]);
	});

	test("가격만 대상은 하루 한도를 쓰지 않는다", () => {
		const open = Array.from({ length: 7 }, (_, index) =>
			listing({ id: `p${index}`, title: `bump ${index}`, price: 10_000, hearts: 0, until: TODAY }),
		);
		const onlyPrice = aimed({ id: "x", title: "가격만", price: 300_000, hearts: 4, target: 295_000 });
		const proposals = planOf([...open, onlyPrice]);
		const summary = summarize(proposals);
		expect(summary.bump).toBe(6);
		expect(summary.priceOnly).toBe(1);
		// 한 칸을 못 받은 끌올 대상과 가격만 내리는 글이 같은 까닭을 달고, 가격은 따로 내린다.
		expect(summary.held).toBe(2);
		expect(proposals.find((proposal) => proposal.id === "p6")).toMatchObject({
			action: "skip",
			skipReason: "daily-limit",
		});
		expect(proposals.find((proposal) => proposal.id === "x")).toMatchObject({
			action: "price-only",
			blocked: "daily-limit",
		});
	});

	test("끌올 문구가 없는 글 → 오래된 끌올 → 제목", () => {
		const older = listing({ id: "old", title: "나", price: 10_000, hearts: 0, bumpAgoDays: 7 });
		const newest = listing({ id: "new", title: "가", price: 10_000, hearts: 0, bumpAgoDays: 2 });
		const never = listing({ id: "never", title: "다", price: 10_000, hearts: 0, bumpAgoDays: null });
		const otherNever = listing({ id: "other", title: "라", price: 10_000, hearts: 0, bumpAgoDays: null });
		const sorted = [newest, older, otherNever, never]
			.sort((left, right) => compareBumpOrder(left, right, TODAY))
			.map((item) => item.id);
		expect(sorted).toEqual(["never", "other", "old", "new"]);
	});

	test("노출 나이·마감이 같으면 제목보다 하트가 먼저다", () => {
		const quiet = listing({ id: "quiet", title: "하", price: 10_000, hearts: 0, bumpAgoDays: 9 });
		const looked = listing({ id: "looked", title: "가", price: 10_000, hearts: 1, bumpAgoDays: 9 });
		const sorted = [looked, quiet].sort((left, right) => compareBumpOrder(left, right, TODAY));
		expect(sorted.map((item) => item.id)).toEqual(["quiet", "looked"]);
	});

