describe("쿨타임과 15회", () => {
	const cooling = (id: string, hearts = 1) =>
		listing({
			id,
			title: id,
			price: 10_000,
			hearts,
			bumpCount: 3,
			bumpedAt: "2026-10-25T01:00:00.000Z",
			nextBumpAt: "2026-10-29T01:00:00.000Z",
		});

	test("다음 끌올 시각이 남았으면 cooldown으로 건너뛴다", () => {
		const [proposal] = planOf([cooling("cy")]);
		expect(proposal.action).toBe("skip");
		expect(proposal.skipReason).toBe("cooldown");
		expect(proposal.nextBumpAt).toBe("2026-10-29T01:00:00.000Z");
	});

	test("다음 끌올 시각이 지났거나 없으면 다시 대상이다", () => {
		const past = { ...cooling("past"), nextBumpAt: new Date(NOW - 1).toISOString() };
		const unknown = { ...cooling("unknown"), nextBumpAt: null };
		expect(planOf([past, unknown]).map((proposal) => proposal.action)).toEqual(["bump", "bump"]);
		expect(bumpEligible(past, NOW)).toBe(true);
		expect(bumpEligible(cooling("cy"), NOW)).toBe(false);
		expect(inCooldown(cooling("cy"), NOW)).toBe(true);
	});

	test("15회를 채운 글은 max-bumps로 건너뛴다", () => {
		const full = { ...cooling("full"), bumpCount: MAX_BUMPS, nextBumpAt: null };
		const [proposal] = planOf([full]);
		expect(proposal.action).toBe("skip");
		expect(proposal.skipReason).toBe("max-bumps");
		expect(atMaxBumps(full)).toBe(true);
		expect(bumpEligible(full, NOW)).toBe(false);
	});

	test("15회는 넘겨도 max-bumps다", () => {
		const [proposal] = planOf([{ ...cooling("over"), bumpCount: MAX_BUMPS + 2 }]);
		expect(proposal.skipReason).toBe("max-bumps");
